import { MembershipItem, MembershipCategory } from './crawledMembershipData';
export type { MembershipItem, MembershipCategory };



// 가격 포맷팅 유틸리티
export const formatPrice = (priceValue: number): string => {
    const eok = Math.floor(priceValue / 100000000);  // 억
    const man = Math.floor((priceValue % 100000000) / 10000);  // 만

    if (eok > 0) {
        if (man > 0) {
            return `${eok}억 ${man.toLocaleString()}만`;
        }
        return `${eok}억`;
    }
    if (man > 0) {
        return `${man.toLocaleString()}만`;
    }
    return `${priceValue.toLocaleString()}원`;
};

// 재판매 리스트 생성 (크롤링 데이터로부터)
// 실제 데이터는 별도 파일에서 import
